ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock,
                                    struct msghdr *msg, size_t len, int flags)
{
    struct sock *sk = sock->sk;
    int copied = 0;
    int err = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (flags & MSG_OOB) {
        // Out-of-band data is not supported in this example
        err = -EOPNOTSUPP;
        goto out;
    }

    copied = min_t(int, skb->len, len);

    if (copied > 0) {
        err = skb_copy_datagram_msg(skb, 0, msg, copied);
        if (err)
            goto out;
    }

    if (skb->len > len) {
        // Message was truncated
        msg->msg_flags |= MSG_TRUNC;
    }

    if (flags & MSG_DONTFREE)
        skb_push(skb, skb->data - skb_network_header(skb));
    else
        kfree_skb(skb);

    out:
    if (skb && !(flags & MSG_DONTFREE))
        kfree_skb(skb);

    if (err)
        return err;

    return copied;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    int error = 0;
    int copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (flags & MSG_OOB) {
        error = -EOPNOTSUPP;
        if (sock->type != SOCK_STREAM)
            return error;
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        if (flags & MSG_DONTWAIT)
            return -EAGAIN;
        error = -EAGAIN;
        return error;
    }

    copied = skb->len;
    if (len < copied) {
        if (!(flags & MSG_TRUNC))
            copied = len;
        else
            copied = skb->len;
    }

    if (skb_copy_datagram_to_iter(skb, 0, &msg->msg_iter, copied))
        return -EFAULT;

    if (skb->len > copied)
        msg->msg_flags |= MSG_TRUNC;

    skb_unlink(skb, &sk->sk_receive_queue);
    kfree_skb(skb);

    return copied;
}

#include <linux/socket.h>
#include <linux/uio.h>
#include <linux/errno.h>

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    int ret = 0;
    struct sock *sk = sock->sk;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    if (flags & MSG_OOB) {
        ret = sock->ops->recv_oob(sk, msg, len, flags);
        if (ret < 0)
            return ret;
    } else {
        struct sk_buff *skb;

        skb = skb_dequeue(&sk->sk_receive_queue);
        if (!skb)
            return -EAGAIN;

        ret = skb->len;
        if (len < ret) {
            if (!(flags & MSG_TRUNC))
                ret = len;
            else
                ret = skb->len;
        }

        if (!skb_copy_datagram_to_iter(skb, 0, &msg->msg_iter, ret)) {
            msg->msg_len = ret;
            sock->ops->release(skb);
        } else {
            ret = -EFAULT;
        }
    }

    sock_update_state(sk);
    return ret;
}

ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    ssize_t copied = 0;
    struct sk_buff *skb;
    struct sock *sk = sock->sk;

    lock_sock(sk);

    if (sk->sk_state == TCP_CLOSE && !(flags & MSG_DONTWAIT)) {
        release_sock(sk);
        return -ENOTCONN;
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        if (flags & MSG_DONTWAIT) {
            release_sock(sk);
            return -EAGAIN;
        }

        while (skb_empty(&sk->sk_receive_queue)) {
            if (signal_pending(current)) {
                release_sock(sk);
                return -ERESTARTSYS;
            }

            wait_for_more_data();
        }

        skb = skb_dequeue(&sk->sk_receive_queue);
    }

    if (skb->len > len) {
        if (flags & MSG_TRUNC) {
            copied = skb->len;
        } else {
            copied = len;
            skb_pull(skb, skb->len - len);
        }
    } else {
        copied = skb->len;
    }

    if (skb_copy_datagram_msg(skb, 0, msg, copied)) {
        release_sock(sk);
        return -EFAULT;
    }

    if (flags & MSG_OOB) {
        handle_oob_data(skb);
    }

    skb_consume_datagram(skb, copied);
    kfree_skb(skb);

    release_sock(sk);
    return copied;
}

#include <linux/socket.h>
#include <linux/slab.h>
#include <linux/uaccess.h>

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    int ret;
    struct sk_buff *skb;

    if (sock->state != SS_CONNECTED)
        return -ENOTCONN;

    skb = skb_dequeue(&sock->recv_queue);
    if (!skb)
        return -EAGAIN;

    ret = skb->len;
    if (len < ret && (flags & MSG_TRUNC)) {
        ret = skb->len;
    } else {
        len = min_t(size_t, len, skb->len);
        if (copy_to_iter(skb->data, len, msg->msg_iter) != len)
            ret = -EFAULT;
    }

    kfree_skb(skb);
    sock->state = SS_DATA_READY;
    return ret;
}
